            "flash_application": FirmwareAction(
                mcp_tool="flash_application",
                method_version=1,
                maximum_duration_seconds=120,
                required_arguments=("board_id", "artifact"),
            ),
        },
        resources={
            "board:stm-a": {
                "probe_uid": "probe-a",
                "target": "stm32l476rg",
                "profile": "stm32",
            },
            "board:nrf-a": {
                "probe_uid": "probe-b",
                "target": "nrf52840",
                "profile": "nrf",
            },
        },
        policy={
            "policy": "caller-declared-policy-v1",
            "revision": "caller-supplied-revision",
